import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z } from "npm:zod@^4.4.3";
var list_modules_default = defineTool2({
  name: "list_modules",
  title: "Listar m\xF3dulos liberados",
  description: "Lista m\xF3dulos + p\xEDlulas de uma eletiva. Respeita `module_releases`: s\xF3 retorna m\xF3dulos que j\xE1 foram liberados pela turma.",
  inputSchema: {
    course_slug: z.string().min(1).describe("slug da eletiva, ex: 'ia-na-pratica' ou 'economia-circular'"),
    include_pills: z.boolean().default(false).describe("se true, inclui as p\xEDlulas de cada m\xF3dulo")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ course_slug, include_pills }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "n\xE3o autenticado" }], isError: true };
    }
    const supabase = supabaseAsUser(ctx);
    const { data: course, error: courseErr } = await supabase.from("courses").select("id, slug, title, description").eq("slug", course_slug).maybeSingle();
    if (courseErr || !course) {
      return {
        content: [{ type: "text", text: `eletiva '${course_slug}' n\xE3o encontrada` }],
        isError: true
      };
    }
    const select = include_pills ? "id, number, title, summary, trail_id, module_pills(id, kind, title, duration_min, order_index)" : "id, number, title, summary, trail_id";
    const { data: modules, error } = await supabase.from("modules").select(select).eq("course_id", course.id).order("number");
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    const payload = { course, modules: modules ?? [] };
    return {
      content: [{ type: "text", text: JSON.stringify(payload, null, 2) }],
      structuredContent: payload
    };
  }
});

