import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z2 } from "npm:zod@^4.4.3";
var submit_evidence_default = defineTool3({
  name: "submit_evidence",
  title: "Registrar evid\xEAncia de m\xF3dulo",
  description: "Envia o registro/s\xEDntese do PBL de um m\xF3dulo em nome do estudante. Grava em `module_deliverables` respeitando RLS.",
  inputSchema: {
    module_id: z2.string().uuid().describe("uuid do m\xF3dulo (use list_modules pra descobrir)"),
    content: z2.string().min(10).max(4e3).describe("texto da s\xEDntese/registro da entrega, 10 a 4000 caracteres"),
    link: z2.string().url().nullable().describe("link opcional do projeto/artefato. passe null se n\xE3o tiver")
  },
  annotations: {
    readOnlyHint: false,
    destructiveHint: false,
    idempotentHint: false,
    openWorldHint: false
  },
  handler: async ({ module_id, content, link }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "n\xE3o autenticado" }], isError: true };
    }
    const supabase = supabaseAsUser(ctx);
    const { data, error } = await supabase.from("module_deliverables").insert({
      module_id,
      user_id: ctx.getUserId(),
      content,
      link,
      status: "submitted"
    }).select().single();
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    return {
      content: [
        { type: "text", text: `entrega registrada. id=${data.id}` }
      ],
      structuredContent: { deliverable: data }
    };
  }
});

